C();		virtual ControlPartCode	TrackMouse(const CPoint_AC& mouseLocation, SInt16 modifiers);	virtual ControlPartCode GetDefaultPartCode() const;			// Track the mouse.		virtual SInt32		GetValue() const;	virtual void		SetValue(SInt32 newValue);		virtual void		SetGroupID(UInt32 groupIDPart1, UInt32 groupIDPart2);	// MExclusiveObject mixin override	virtual void		TurnOff();	// MExclusiveObject mixin override	static void			AllocateRadioImages();	static void			DisposeRadioImages();protected:	virtual void		DrawButtonNormal(bool deep);	virtual void		DrawButtonPressed(bool deep);	virtual void		DrawButtonDisabled(bool deep);		void				CopyImage(UInt32 index);		SInt32				fValue;	bool				fAutomaticState;	// if true, radio is set on click w/o caller needing to call SetValue		// Drawing the 3D radio button manually is just too damn tedious.	// So we use offscreen PixMap structures and blast them onto the screen.	// The mask (clip) region for the images is a round rectangle.	enum { kRadioImageWidth = 12, kRadioImageHeight = 12 };	enum { kRadioNormalOff, kRadioNormalOn, kRadioNormalMixed,			kRadioPressedOff, kRadioPressedOn, kRadioPressedMixed,			kRadioDisabledOff, kRadioDisabledOn, kRadioDisabledMixed,			kNumRadioImages };		static bool			fgImagesAllocated;	static SInt8		kRadioImageValues[kNumRadioImages]										[kRadioImageHeight]										[kRadioImageWidth];	static CAutoPtr_AC<CSimpleOffscreenImage_AC>	fgOffscreenRadioImages[kNumRadioImages];};/*	Historical Change Record:		----- R13 -----		07/14/97	Missing CAutoPtr_AC.h include.		06/05/97	EXPORT_AC, EXPORT_MA, no-load fixes, Memory_AC, Windows_AC, no CW11orLATER, removed segmentation, etc...		04/16/97	Removed redundant constructor.		04/14/97	Update for real xxx_cast operators.		03/25/97	AC_ to _AC Name change.		03/15/97	Split out.		02/25/97	Merged Gray Council 2.1 changes.		02/07/97	First check in.*/#endif // qEmulateStandardControls#endif // __CRadioButton_AC__